            WHERE LOWER(account_group) = LOWER(par_AccountGroup) AND LOWER(amount_in_doc_curr) <> LOWER('0.00')
        ORDER BY text NULLS FIRST, sno NULLS FIRST
        LIMIT 10000) UNION ALL
