        UNION ALL
        SELECT
            NULL AS expr1, 'Counter' AS column1, 'Doc_Date' AS column2, 'Pstg date' AS column3, 'Type' AS column4, 'CoCd' AS column5, 'CURR' AS column6, 'TranslDate' AS column7, 'Exchange_Rate' AS column8, 'Ledger_Group' AS column9, 'Period' AS column10, 'Reference' AS column11, 'Document_header_text' AS column12, 'PK' AS column13, 'GL_acct' AS column14, 'SpecialGL' AS column15, 'Amount_in_doc_curr' AS column16, 'Amount_in_local_curr' AS column17, 'Amount_in_local_cur_2' AS column18, 'Ref_key_1' AS column19, 'Ref_key_2' AS column20, 'Ref_key_3' AS column21, 'Bline_date' AS column22, 'Purch_doc' AS column23, 'PurchasingLineItem' AS column24, 'WBS_Element' AS column25, 'Material' AS column26, 'Plnt' AS column27, 'Value_date' AS column28, 'PayT' AS column29, 'Order' AS column30, 'Cost_ctr' AS column31, 'Profit_ctr' AS column32, 'Partner_Profit_Center' AS column33, 'Tr_prt' AS column34, 'Assignment' AS column35, 'Text' AS column36, 'Quantity' AS column37, 'UoM' AS column38, 'Brand' AS column39, 'SubProduct_A' AS column40, 'SubProduct_B' AS column41, 'Franchise_Area' AS column42, 'Business_Center' AS column43, 'Revenue_Type' AS column44, 'Event' AS column45, 'Vat_Tax_Code' AS column46, 'MVNO Partner' AS column47, 'Technology' AS column48, 'Charge Code' AS column49, 'Plan Type' AS column50, 'Name' AS column51, 'Street' AS column52, 'Country' AS column53, 'Postal Code' AS column54, 'City' AS column55, 'Bank Key' AS column56, 'Bank Account' AS column57, 'Tax Number' AS column58, 'General Ledger Account' AS column59, 'Message' AS column60, 'Main Asset Number' AS column61, 'Base Tax Amount' AS column62, 'Withholding Tax Type' AS column63, 'Withholding Tax Code' AS column64, 'Payment Method' AS column65, 'New Company Code' AS column66, 'Local file for upload/download' AS column67, 'Error Flag' AS column68, 'core product' AS column69, 'Product lines' AS column70, 'DSP_Order' AS column71, 'DSP_UniqueKey' AS column72, 'Z_MESSAGE' AS column73, 'Z_SOURCE_NAME' AS column74
